    31→wss.on('connection', (ws, req) => {
    32→  const { query } = url.parse(req.url, true);
    33→  const token = query.token;
    34→  if (!token) { ws.close(); return; }
    35→  try {
    36→    const decoded = jwt.verify(token, process.env.JWT_SECRET);
    37→    const userId = decoded.id;
    38→    registerWsClient(userId, ws);
    39→    ws.send(JSON.stringify({ type: 'connected', message: 'متصل بالإشعارات الفورية' }));
    40→    ws.on('close', () => unregisterWsClient(userId));
    41→    ws.on('error', () => unregisterWsClient(userId));
    42→  } catch {
    43→    ws.close();
    44→  }
    45→});
