node -e "
const sharp = require('./server/node_modules/sharp');
const path = require('path');

async function generateIcons() {
  const src = path.join('client/public/logo-transparent.png');

  // Get metadata
  const meta = await sharp(src).metadata();
  console.log('Source:', meta.width, 'x', meta.height, 'channels:', meta.channels);

  // Trim whitespace and generate icons
  const sizes = [
    { size: 16, name: 'favicon-16.png' },
    { size: 32, name: 'favicon-32.png' },
    { size: 180, name: 'apple-touch-icon.png' },
    { size: 192, name: 'icon-192.png' },
    { size: 512, name: 'icon-512.png' },
  ];

  for (const { size, name } of sizes) {
    const padding = Math.floor(size * 0.08); // 8% padding
    const inner = size - padding * 2;

    await sharp(src)
      .trim({ background: { r: 255, g: 255, b: 255, alpha: 0 }, threshold: 30 })
      .resize(inner, inner, { fit: 'contain', background: { r: 255, g: 255, b: 255, alpha: 0 } })
      .extend({ top: padding, bottom: padding, left: padding, right: padding, background: { r: 255, g: 255, b: 255, alpha: 0 } })
      .png()
      .toFile(path.join('client/public', name));

    console.log('Generated:', name, size+'x'+size);
  }

  // Also generate a maskable icon (logo centered in colored background)
  const maskPad = Math.floor(512 * 0.2);
  const maskInner = 512 - maskPad * 2;
  await sharp(src)
    .trim({ background: { r: 255, g: 255, b: 255, alpha: 0 }, threshold: 30 })
    .resize(maskInner, maskInner, { fit: 'contain', background: { r: 255, g: 255, b: 255, alpha: 0 } })
    .extend({ top: maskPad, bottom: maskPad, left: maskPad, right: maskPad, background: { r: 37, g: 99, b: 235, alpha: 1 } })
    .flatten({ background: { r: 37, g: 99, b: 235 } })
    .png()
    .toFile('client/public/icon-maskable.png');
  console.log('Generated: icon-maskable.png 512x512');
}

generateIcons().catch(console.error);
" 2>&1

